def smallest_change(arr):
    # Your code here.

    def check(ls):
        if list(map(lambda x, _y: x,ls,ls[::-1])) == ls:
            return 0
        else:
            ls = ls + ls[::-1]
            tmp = {}
            for i in range(len(ls)):
                if ls[i] in tmp:
                    tmp[ls[i]] += 1
                else:
                    tmp[ls[i]] = 1
            return min(tmp.values())
    
    arr = list(dict(sorted((x,i) for i,x in enumerate(arr))).values())
    return check(arr) + check(arr[::-1])
   
